	@Test
	void bulkPersistenceReloadsRealSnapshotAndKeepsLiveEstimatorUsable(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path dataDir = evidence.resolve("live-store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setSketchEstimatorEnabled(true)
				.setSketchEstimatorMemoryBudgetBytes(SMALL_BUDGET)
				.setSketchEstimatorColdSynopsisCapacity(64);
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		store.setExperimentalQueryOptimizations(true);
		SailRepository repository = new SailRepository(store);
		try {
			BenchmarkJoinEstimatorSupport.prepareEstimatorForBulkLoad(repository, store);
			addStatement(repository, "first", 1);
			assertTrue(store.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = BenchmarkJoinEstimatorSupport.resolveEstimator(store);
			estimator.persistIfDirty();
			Path original = dataDir.resolve(SNAPSHOT);
			assertTrue(Files.isRegularFile(original));
			Path backup = evidence.resolve("original-v8.bin");
			Files.copy(original, backup);
			long version = estimator.snapshotVersion();
			var identity = estimator.quadSnapshotIdentity();

			BenchmarkJoinEstimatorSupport.persistEstimatorAfterBulkLoad(repository, store);

			assertTrue(estimator.isReadyNonBlocking(), "the repository's estimator must remain live");
			assertEquals(identity, estimator.quadSnapshotIdentity());
			assertEquals(version, estimator.snapshotVersion());
			assertEquals(-1L, Files.mismatch(original, backup), "the persisted snapshot must remain unchanged");
			assertEquals(1.0d, predicateRows(estimator));
			Path verifyDir = evidence.resolve("independent-reload");
			Files.createDirectories(verifyDir);
			Files.copy(original, verifyDir.resolve("synopsis-v8.bin"));
			SketchBasedJoinEstimator.Config reloadConfig = SketchBasedJoinEstimator.Config.defaults()
					.withMemoryBudgetBytes(SMALL_BUDGET)
					.withColdSynopsisCapacity(64);
			try (SketchBasedJoinEstimator reloaded = new SketchBasedJoinEstimator((s, p, o, c) -> {
				throw new AssertionError("a valid persisted snapshot must not scan the source");
			}, reloadConfig)) {
				reloaded.configurePersistence(verifyDir, true);
				assertTrue(reloaded.isReadyNonBlocking(), "a valid v8 snapshot loads synchronously");
				assertEquals(identity, reloaded.quadSnapshotIdentity());
				assertEquals(version, reloaded.snapshotVersion());
				assertEquals(1.0d, predicateRows(reloaded));
			}

			assertEquals(1L, countByQuery(repository));
			addStatement(repository, "second", 2);
			assertEquals(2L, countByQuery(repository));
			assertTrue(store.forceFlushSketchEstimator());
			assertTrue(estimator.isReadyNonBlocking(), "queries after the helper must retain a usable estimator");
			assertEquals(2.0d, predicateRows(estimator));
		} finally {
			repository.shutDown();
		}
	}

