			preserveFixtureTree(first.storeDirectory(), evidence.resolve("initial-store-backup"));
			Path snapshot = first.storeDirectory().resolve(SNAPSHOT);
			Path propertiesPath = first.storeDirectory().resolve("expected-db-file-sizes.properties");
			Properties properties = new Properties();
			try (var input = Files.newInputStream(propertiesPath)) {
				properties.load(input);
			}
			properties.remove("synopsis.v8.fingerprint");
			properties.remove("synopsis.v8.sha256");
			try (var output = Files.newOutputStream(propertiesPath)) {
				properties.store(output, "legacy size evidence");
			}
			Path backup = evidence.resolve("preserved-legacy");
			Files.createDirectories(backup);
			Files.copy(snapshot, backup.resolve("synopsis-v8.bin"));
			Files.copy(propertiesPath, backup.resolve("expected-db-file-sizes.properties"));
			Path sentinel = first.storeDirectory().resolve("must-not-be-deleted.txt");
			Files.writeString(sentinel, "preserve the cache");

			preserveFixtureTree(first.storeDirectory(), evidence.resolve("legacy-input-store-backup"));
			var reused = BenchmarkJoinEstimatorSupport.preparePersistentThemeRegressionStore("fixture/legacy-v8",
					directory -> fail("a validated legacy v8 cache must not be rebuilt or deleted"));

			assertTrue(reused.reused());
			assertEquals(-1L, Files.mismatch(snapshot, backup.resolve("synopsis-v8.bin")));
			assertTrue(Files.exists(sentinel));
